create extension if not exists pgcrypto;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade, strengths jsonb not null default '[]', career_goals text not null default '', avoid_work text not null default '', desired_rate integer, desired_work_style text, weight_experience integer not null default 50 check(weight_experience between 0 and 100), weight_career integer not null default 30 check(weight_career between 0 and 100), weight_tech integer not null default 20 check(weight_tech between 0 and 100), check(weight_experience+weight_career+weight_tech=100));
create table public.skill_sheets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,file_path text not null,extracted jsonb not null,created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,source_text text not null default '',source_file_path text,requirements jsonb not null default '{}',rate integer,location text,work_style text,sales_contact text,status text not null default 'proposed',created_at timestamptz not null default now());
create table public.match_results(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,total_score integer not null check(total_score between 0 and 100),tech_score integer not null check(tech_score between 0 and 100),experience_score integer not null check(experience_score between 0 and 100),career_score integer not null check(career_score between 0 and 100),detail jsonb not null,created_at timestamptz not null default now());
create index skill_sheets_user_latest on public.skill_sheets(user_id,created_at desc); create index projects_user_latest on public.projects(user_id,created_at desc); create index matches_project_latest on public.match_results(project_id,created_at desc);
do $$ declare t text; begin foreach t in array array['profiles','skill_sheets','projects','match_results'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy "owner access" on public.%I for all using (user_id=auth.uid()) with check(user_id=auth.uid())',t); end loop; end $$;
insert into storage.buckets(id,name,public) values('private-documents','private-documents',false) on conflict(id) do nothing;
create policy "private files owner access" on storage.objects for all using(bucket_id='private-documents' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='private-documents' and (storage.foldername(name))[1]=auth.uid()::text);
